import 'dart:convert';import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../core/app_state.dart';
class ReceiveScreen extends StatefulWidget{const ReceiveScreen({super.key});@override State<ReceiveScreen>createState()=>_ReceiveScreenState();}class _ReceiveScreenState extends State<ReceiveScreen>{final email=TextEditingController(),password=TextEditingController(),totp=TextEditingController(),code=TextEditingController();String result='';bool logged=false;Future<void>login()async{try{await context.read<AppState>().api.login(email.text,password.text,totp:totp.text);setState(()=>logged=true);}catch(e){setState(()=>result='$e');}}Future<void>redeem()async{try{final r=await context.read<AppState>().api.redeem(code.text);setState(()=>result=const JsonEncoder.withIndent('  ').convert(r));}catch(e){setState(()=>result='$e');}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Receive secure file')),body:SingleChildScrollView(padding:const EdgeInsets.all(28),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:650),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('Authenticate and redeem',style:Theme.of(c).textTheme.headlineMedium),const SizedBox(height:20),if(!logged)...[TextField(controller:email,decoration:const InputDecoration(labelText:'Email')),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password')),TextField(controller:totp,decoration:const InputDecoration(labelText:'TOTP code')),const SizedBox(height:12),FilledButton(onPressed:login,child:const Text('Sign in'))]else...[TextField(controller:code,decoration:const InputDecoration(labelText:'Share code',hintText:'XC-ABCD-EFGH-IJKL')),const SizedBox(height:12),FilledButton(onPressed:redeem,child:const Text('Redeem code'))],if(result.isNotEmpty)...[const SizedBox(height:20),SelectableText(result)] ]))));}
